mapper.select:
/*	senseQuality.selectSenseQualityCount */
	SELECT
		count(REPORT_IDX) as cnt
	FROM
		lab_sense_quality_report
	WHERE 1 = 1
		
			 
			AND DOC_OWNER = #{userId} 
			
		    
		    AND DOC_OWNER IN (
		    	SELECT USER_ID from lab_team_manager_view ltmv
				WHERE ltmv.TEAM_MANAGER_ID = #{userId}
		    ) 
		    
		    
		    
		    
			 AND DOC_OWNER = #{userId} 
		
		AND IS_DELETE = 'N'

/* senseQuality.selectSenseQualityList */ SELECT tmp.REPORT_IDX , tmp.TITLE , tmp.COMPANY_NAME , tmp.PRODUCT_NAME , tmp.SAP_CODE , tmp.TEST_PURPOSE , tmp.CONTENTS_HEADER , tmp.IS_DELETE , tmp.REG_USER , DATE_FORMAT(tmp.REG_DATE, '%Y-%m-%d') as REG_DATE , tmp.STATUS , tmp.DOC_OWNER , FN_GET_USER_NAME(tmp.REG_USER) as REG_USER_NAME , FN_GET_CODE_NAME('DOC_STATUS', tmp.STATUS) AS STATUS_TXT FROM ( SELECT row_number() over (order by REPORT_IDX DESC) as rnum , REPORT_IDX , TITLE , COMPANY_NAME , PRODUCT_NAME , SAP_CODE , TEST_PURPOSE , CONTENTS_HEADER , IS_DELETE , REG_USER , REG_DATE , STATUS , DOC_OWNER FROM lab_sense_quality_report WHERE 1 = 1
AND DOC_OWNER = #{userId}
AND DOC_OWNER IN ( SELECT USER_ID from lab_team_manager_view ltmv WHERE ltmv.TEAM_MANAGER_ID = #{userId} )
AND DOC_OWNER = #{userId}
AND IS_DELETE = 'N'
)tmp WHERE rnum between #{startRow} and #{endRow}

mapper.insert:
/*	senseQuality.insertSenseQualityReport */
INSERT INTO lab_sense_quality_report(
	REPORT_IDX
	, TITLE
	, COMPANY_NAME
	, PRODUCT_NAME
	, SAP_CODE
	, TEST_PURPOSE
	, CONTENTS_HEADER
	, STATUS
	, IS_DELETE
	, REG_USER
	, REG_DATE
	, DOC_OWNER			
)VALUES(
	#{idx}
	, #{title} 
	, #{companyName}
	, #{productName}
	, #{sapCode}
	, #{testPurpose}
	, #{contentsHeader}
	, #{status}
	, 'N'
	, #{userId}
	, sysdate()
	, #{userId}
)

mapper.update:
/*	senseQuality.updateSenseQualityReport */
UPDATE 
	lab_sense_quality_report
SET
	TITLE = #{title}
	, COMPANY_NAME = #{companyName}
	, PRODUCT_NAME = #{productName}
	, SAP_CODE = #{sapCode}
	, TEST_PURPOSE = #{testPurpose}
	, CONTENTS_HEADER = #{contentsHeader}
	, STATUS = #{status}
WHERE 1 = 1
	AND REPORT_IDX = #{idx}

/*	senseQuality.updateSenseQualityContent */
UPDATE
	lab_sense_quality_contents
SET 
	CONTENTS_DIV = #{contentsDiv}
	, CONTENTS_RESULT = #{contentsResult}
	
		, FILE_PATH = #{filePath}
		, FILE_NAME = #{orgFileName}
		, ORG_FILE_NAME = #{changeFileName}
	
WHERE 1 = 1
	AND CONTENTS_IDX = #{contentsIdx}

mapper.delete:
/*	senseQuality.deleteSenseQualityAddInfo */
DELETE 
FROM 
	lab_sense_quality_add_info
WHERE 1 = 1
	AND REPORT_IDX = #{idx}

/*	senseQuality.deleteSenseQualityContenstsData */
DELETE
FROM 
	lab_sense_quality_contents
WHERE 1 = 1
	AND CONTENTS_IDX = #{contentsIdx}
